"""Conservative marker matching in a common physical coordinate frame."""
from .parser import DRCReportData
from .marker_geometry import BoxMarker, EdgeMarker, EdgePairMarker, PolygonMarker


def canonical_geometry(geometry):
    marker = geometry.marker
    def edge(value):
        return tuple(sorted(((value.p1.x, value.p1.y), (value.p2.x, value.p2.y))))
    if isinstance(marker, BoxMarker):
        return ("box", marker.bbox)
    if isinstance(marker, EdgeMarker):
        return ("edge", edge(marker))
    if isinstance(marker, EdgePairMarker):
        return ("edge_pair", tuple(sorted((edge(marker.edge1), edge(marker.edge2)))))
    if isinstance(marker, PolygonMarker):
        points = [(p.x, p.y) for p in marker.points]
        if points and points[0] == points[-1]:
            points.pop()
        rotations = [tuple(seq[i:]+seq[:i]) for seq in (points, list(reversed(points))) for i in range(len(seq))]
        return ("polygon", min(rotations) if rotations else (), geometry.representation if "/" in geometry.representation else "")
    return (geometry.kind, geometry.representation)


def marker_records(report: DRCReportData) -> list[dict]:
    records = []
    for category in report.categories:
        for item in category.violations:
            records.append({"rule": category.name, "cell": item.cell_name,
                            "geometry": sorted((canonical_geometry(g) for g in item.geometries), key=str),
                            "boxes": sorted(g.bbox_um for g in item.geometries if g.bbox_um is not None)})
    return sorted(records, key=lambda r: (r["rule"], r["cell"], str(r["geometry"])))


def compare_markers(before: DRCReportData, after: DRCReportData, grid_um: float) -> dict:
    """Exact identity first, then mutual unique matches within one grid step.

    Reports from different checker frames must not be compared. The caller enforces
    identical deck, profile, top cell and parameters. Unknown geometry is ambiguous.
    """
    left, right = marker_records(before), marker_records(after)
    remaining = set(range(len(right)))
    pending = []
    persisted = 0
    for record in left:
        matches = [j for j in sorted(remaining) if right[j] == record and record["boxes"]]
        if matches:
            remaining.remove(matches[0]); persisted += 1
        else:
            pending.append(record)

    def close(a, b):
        return (a["rule"] == b["rule"] and a["cell"] == b["cell"]
                and len(a["boxes"]) == len(b["boxes"]) and bool(a["boxes"])
                and all(abs(x-y) <= grid_um + 1e-12
                        for box_a, box_b in zip(a["boxes"], b["boxes"])
                        for x, y in zip(box_a, box_b)))

    links = {i: [j for j in sorted(remaining) if close(a, right[j])] for i, a in enumerate(pending)}
    matched_left, matched_right = set(), set()
    ambiguous_left, ambiguous_right = set(), set()
    for i, js in links.items():
        if len(js) == 1 and sum(js[0] in other for other in links.values()) == 1:
            matched_left.add(i); matched_right.add(js[0]); persisted += 1
        elif js:
            ambiguous_left.add(i); ambiguous_right.update(js)
        elif not pending[i]["boxes"]:
            ambiguous_left.add(i)
    ambiguous_right.update(j for j in remaining if not right[j]["boxes"])
    return {"persisted": persisted,
            "resolved": len(pending) - len(matched_left | ambiguous_left),
            "introduced": len(remaining - matched_right - ambiguous_right),
            "ambiguous": len(ambiguous_left) + len(ambiguous_right),
            "tolerance_um": grid_um, "frame": "checker_cell", "method": "exact_then_mutual_unique_bbox"}

src/klayout_drc/marker_geometry.py:
"""Typed geometric representations for KLayout ReportDatabase (RDB) markers.

Provides strongly typed marker geometry models (EdgeMarker, EdgePairMarker,
PolygonMarker, BoxMarker) with physical coordinate conversions and spatial hashing.
"""

from dataclasses import dataclass
import math
from typing import Any


@dataclass(frozen=True)
class Point:
    """A 2D coordinate in physical micrometers."""

    x: float
    y: float

    def distance_to(self, other: "Point") -> float:
        """Euclidean distance to another point."""
        return math.hypot(self.x - other.x, self.y - other.y)

    def quantize(self, precision: float = 0.0001) -> "Point":
        """Return point with coordinates rounded to given precision."""
        return Point(
            x=round(self.x / precision) * precision,
            y=round(self.y / precision) * precision,
        )


@dataclass(frozen=True)
class EdgeMarker:
    """A directed edge violation marker."""

    p1: Point
    p2: Point

    @property
    def length_um(self) -> float:
        """Physical length in micrometers."""
        return self.p1.distance_to(self.p2)

    @property
    def bbox(self) -> tuple[float, float, float, float]:
        """(min_x, min_y, max_x, max_y) bounding box."""
        return (
            min(self.p1.x, self.p2.x),
            min(self.p1.y, self.p2.y),
            max(self.p1.x, self.p2.x),
            max(self.p1.y, self.p2.y),
        )


@dataclass(frozen=True)
class EdgePairMarker:
    """A pair of edges representing a spacing, width, or enclosure violation."""

    edge1: EdgeMarker
    edge2: EdgeMarker

    @property
    def separation_um(self) -> float:
        """Estimated separation distance between the two edges."""
        # Midpoint to midpoint distance as a representative separation
        mid1 = Point((self.edge1.p1.x + self.edge1.p2.x) / 2.0, (self.edge1.p1.y + self.edge1.p2.y) / 2.0)
        mid2 = Point((self.edge2.p1.x + self.edge2.p2.x) / 2.0, (self.edge2.p1.y + self.edge2.p2.y) / 2.0)
        return mid1.distance_to(mid2)

    @property
    def bbox(self) -> tuple[float, float, float, float]:
        """(min_x, min_y, max_x, max_y) bounding box covering both edges."""
        b1 = self.edge1.bbox
        b2 = self.edge2.bbox
        return (
            min(b1[0], b2[0]),
            min(b1[1], b2[1]),
            max(b1[2], b2[2]),
            max(b1[3], b2[3]),
        )


@dataclass(frozen=True)
class PolygonMarker:
    """A polygon boundary violation marker."""

    points: tuple[Point, ...]

    @property
    def bbox(self) -> tuple[float, float, float, float]:
        """(min_x, min_y, max_x, max_y) bounding box."""
        xs = [p.x for p in self.points]
        ys = [p.y for p in self.points]
        return (min(xs), min(ys), max(xs), max(ys))

    @property
    def area_um2(self) -> float:
        """Area computed via surveyor's formula."""
        n = len(self.points)
        if n < 3:
            return 0.0
        area = 0.0
        for i in range(n):
            j = (i + 1) % n
            area += self.points[i].x * self.points[j].y
            area -= self.points[j].x * self.points[i].y
        return abs(area) / 2.0


@dataclass(frozen=True)
class BoxMarker:
    """An axis-aligned rectangular violation marker."""

    x1: float
    y1: float
    x2: float
    y2: float

    @property
    def bbox(self) -> tuple[float, float, float, float]:
        """(min_x, min_y, max_x, max_y) bounding box."""
        return (
            min(self.x1, self.x2),
            min(self.y1, self.y2),
            max(self.x1, self.x2),
            max(self.y1, self.y2),
        )

    @property
    def width_um(self) -> float:
        return abs(self.x2 - self.x1)

    @property
    def height_um(self) -> float:
        return abs(self.y2 - self.y1)

    @property
    def area_um2(self) -> float:
        return self.width_um * self.height_um


class MarkerGeometry:
    """Factory and parser for converting KLayout RDB item values into typed markers."""

    @staticmethod
    def parse_value_string(raw_val: str, kind: str | None = None) -> EdgePairMarker | EdgeMarker | PolygonMarker | BoxMarker | None:
        """Parse native KLayout RDB string representations into typed markers.

        Handles:
          - edge-pair: (x1,y1;x2,y2)|(x3,y3;x4,y4) or (x1,y1;x2,y2)/(x3,y3;x4,y4)
          - edge: (x1,y1;x2,y2)
          - polygon: ((x1,y1),(x2,y2),...)
          - box: (x1,y1;x2,y2)
        """
        raw = raw_val.strip()

        if kind == "edge_pair" or raw.startswith("edge-pair:") or ("|" in raw and ";" in raw) or ("/" in raw and ";" in raw):
            body = raw
            if body.startswith("edge-pair:"):
                body = body[len("edge-pair:"):].strip()
            delim = "|" if "|" in body else ("/" if "/" in body else None)
            if delim:
                parts = body.split(delim)
                e1 = MarkerGeometry._parse_single_edge(parts[0].strip())
                e2 = MarkerGeometry._parse_single_edge(parts[1].strip())
                if e1 and e2:
                    return EdgePairMarker(edge1=e1, edge2=e2)

        if kind == "edge" or raw.startswith("edge:"):
            body = raw
            if body.startswith("edge:"):
                body = body[len("edge:"):].strip()
            return MarkerGeometry._parse_single_edge(body)

        if kind == "box" or raw.startswith("box:"):
            body = raw
            if body.startswith("box:"):
                body = body[len("box:"):].strip()
            body = body.strip("()")
            parts = body.split(";")
            if len(parts) == 2:
                p1 = MarkerGeometry._parse_point(parts[0])
                p2 = MarkerGeometry._parse_point(parts[1])
                if p1 and p2:
                    return BoxMarker(x1=p1.x, y1=p1.y, x2=p2.x, y2=p2.y)

        if kind == "polygon" or raw.startswith("polygon:"):
            body = raw
            if body.startswith("polygon:"):
                body = body[len("polygon:"):].strip()
            body = body.strip("()")
            pts: list[Point] = []
            tokens = body.replace("),(", ");(").split(";")
            for tok in tokens:
                p = MarkerGeometry._parse_point(tok)
                if p:
                    pts.append(p)
            if len(pts) >= 3:
                return PolygonMarker(points=tuple(pts))

        return None

    @staticmethod
    def _parse_point(token: str) -> Point | None:
        """Parse (x,y) string into Point."""
        cleaned = token.strip().strip("()")
        coords = cleaned.split(",")
        if len(coords) == 2:
            try:
                return Point(x=float(coords[0].strip()), y=float(coords[1].strip()))
            except ValueError:
                return None
        return None

    @staticmethod
    def _parse_single_edge(token: str) -> EdgeMarker | None:
        """Parse (x1,y1;x2,y2) string into EdgeMarker."""
        cleaned = token.strip().strip("()")
        pts = cleaned.split(";")
        if len(pts) == 2:
            p1 = MarkerGeometry._parse_point(pts[0])
            p2 = MarkerGeometry._parse_point(pts[1])
            if p1 and p2:
                return EdgeMarker(p1=p1, p2=p2)
        return None

