"""Parser for KLayout DRC Report Databases (.lyrdb) and layout targets.

Extracts rule violation categories, individual violation geometries,
coordinates, and multiplicities into strongly-typed data structures.
"""

from dataclasses import dataclass, field
from pathlib import Path
from typing import Any
import klayout.rdb as rdb
import klayout.db as db

from .config import DRCParserError
from .marker_geometry import (
    BoxMarker,
    EdgeMarker,
    EdgePairMarker,
    MarkerGeometry,
    PolygonMarker,
)


@dataclass
class ViolationGeometry:
    """Represents a geometric shape causing a rule violation."""
    kind: str  # 'polygon', 'box', 'edge', 'edge_pair', 'path', 'text', 'shape'
    representation: str
    details: dict[str, Any] = field(default_factory=dict)
    marker: EdgePairMarker | EdgeMarker | PolygonMarker | BoxMarker | None = None

    @property
    def bbox_um(self) -> tuple[float, float, float, float] | None:
        """Bounding box (min_x, min_y, max_x, max_y) in physical micrometers."""
        if self.marker and hasattr(self.marker, "bbox"):
            return self.marker.bbox
        return None


@dataclass
class ViolationItem:
    """An individual DRC violation instance."""
    item_id: int
    category_name: str
    cell_name: str
    geometries: list[ViolationGeometry] = field(default_factory=list)


@dataclass
class RuleCategory:
    """A DRC rule category containing violations."""
    name: str
    description: str
    violations: list[ViolationItem] = field(default_factory=list)

    @property
    def count(self) -> int:
        """Total number of violations for this rule."""
        return len(self.violations)


@dataclass
class DRCReportData:
    """Structured collection of all violations discovered during DRC."""
    source_path: Path
    categories: list[RuleCategory] = field(default_factory=list)

    @property
    def total_violations(self) -> int:
        """Total count of all violations across all rules."""
        return sum(cat.count for cat in self.categories)

    @property
    def rule_summary(self) -> dict[str, int]:
        """Summary mapping rule category names to violation counts."""
        return {cat.name: cat.count for cat in self.categories}

    def to_dict(self) -> dict[str, Any]:
        """Serialize data to a dictionary suitable for JSON serialization."""
        return {
            "source_path": str(self.source_path),
            "total_violations": self.total_violations,
            "rules": [
                {
                    "name": cat.name,
                    "description": cat.description,
                    "count": cat.count,
                    "violations": [
                        {
                            "item_id": v.item_id,
                            "cell": v.cell_name,
                            "geometries": [
                                {
                                    "kind": g.kind,
                                    "representation": g.representation,
                                    "details": g.details,
                                }
                                for g in v.geometries
                            ],
                        }
                        for v in cat.violations
                    ],
                }
                for cat in self.categories
            ],
        }


class DRCParser:
    """Parses KLayout report databases (.lyrdb) and target GDS files."""

    def parse(self, report_path: Path) -> DRCReportData:
        """Parse the given report file into a structured DRCReportData model.

        Args:
            report_path: Path to the .lyrdb file or fallback .target.gds file.

        Returns:
            DRCReportData: Strongly-typed structured report data.

        Raises:
            DRCParserError: If the report file cannot be read or parsed.
        """
        report_path = report_path.resolve()
        if not report_path.exists():
            raise DRCParserError(f"Report file not found: {report_path}")

        # Check if the file is a ReportDatabase (.lyrdb)
        if report_path.suffix == ".lyrdb" or self._is_lyrdb_content(report_path):
            return self._parse_lyrdb(report_path)

        # Fallback to layout file parsing
        if report_path.suffix in (".gds", ".oas"):
            return self._parse_layout(report_path)

        raise DRCParserError(f"Unsupported report format: {report_path.suffix}")

    def _is_lyrdb_content(self, path: Path) -> bool:
        """Check if file starts with XML report-database header."""
        try:
            with open(path, "rb") as f:
                header = f.read(256)
                return b"<report-database" in header
        except OSError:
            return False

    def _parse_lyrdb(self, lyrdb_path: Path) -> DRCReportData:
        """Parse standard KLayout ReportDatabase."""
        report = rdb.ReportDatabase()
        try:
            report.load(str(lyrdb_path))
        except RuntimeError as exc:
            raise DRCParserError(f"Failed to load KLayout report database: {exc}") from exc

        categories: list[RuleCategory] = []
        for cat in report.each_category():
            cat_name = cat.name().strip("'\"")
            rule_cat = RuleCategory(name=cat_name, description=cat.description or "")
            items = [item for item in report.each_item() if item.category_id() == cat.rdb_id()]

            for idx, item in enumerate(items, 1):
                # Retrieve cell name if available
                cell_name = ""
                try:
                    cell_obj = report.cell_by_id(item.cell_id())
                    cell_name = cell_obj.name() if cell_obj else ""
                except Exception:
                    pass

                v_item = ViolationItem(
                    item_id=idx,
                    category_name=cat_name,
                    cell_name=cell_name,
                )

                for val in item.each_value():
                    kind = "shape"
                    rep = val.to_s()
                    if val.is_polygon():
                        kind = "polygon"
                        rep = val.polygon().to_s()
                    elif val.is_box():
                        kind = "box"
                        rep = val.box().to_s()
                    elif val.is_edge():
                        kind = "edge"
                        rep = val.edge().to_s()
                    elif val.is_edge_pair():
                        kind = "edge_pair"
                        rep = val.edge_pair().to_s()
                    elif val.is_path():
                        kind = "path"
                        rep = val.path().to_s()
                    elif val.string:
                        kind = "text"
                        rep = val.string

                    marker = MarkerGeometry.parse_value_string(rep, kind=kind)
                    v_item.geometries.append(
                        ViolationGeometry(kind=kind, representation=rep, marker=marker)
                    )

                rule_cat.violations.append(v_item)

            if rule_cat.count > 0:
                categories.append(rule_cat)

        return DRCReportData(source_path=lyrdb_path, categories=categories)

    def _parse_layout(self, gds_path: Path) -> DRCReportData:
        """Parse fallback layout (.gds) containing error markers."""
        layout = db.Layout()
        try:
            layout.read(str(gds_path))
        except RuntimeError as exc:
            raise DRCParserError(f"Failed to read layout file: {exc}") from exc

        categories: list[RuleCategory] = []
        for layer_index in layout.layer_indexes():
            layer_info = layout.get_info(layer_index)
            cat_name = f"Layer_{layer_info.layer}_{layer_info.datatype}"
            cat_desc = f"Violations on layer {layer_info.layer}/{layer_info.datatype}"
            rule_cat = RuleCategory(name=cat_name, description=cat_desc)

            violation_idx = 1
            for cell in layout.each_cell():
                shapes = cell.shapes(layer_index)
                for shape in shapes.each():
                    v_item = ViolationItem(
                        item_id=violation_idx,
                        category_name=cat_name,
                        cell_name=cell.name,
                    )
                    if shape.is_polygon():
                        v_item.geometries.append(
                            ViolationGeometry(kind="polygon", representation=shape.polygon.to_s())
                        )
                    elif shape.is_box():
                        v_item.geometries.append(
                            ViolationGeometry(kind="box", representation=shape.box.to_s())
                        )
                    elif shape.is_path():
                        v_item.geometries.append(
                            ViolationGeometry(kind="path", representation=shape.path.to_s())
                        )
                    elif shape.is_edge():
                        v_item.geometries.append(
                            ViolationGeometry(kind="edge", representation=shape.edge.to_s())
                        )
                    elif shape.is_text():
                        v_item.geometries.append(
                            ViolationGeometry(kind="text", representation=shape.text.string)
                        )
                    else:
                        v_item.geometries.append(
                            ViolationGeometry(kind="shape", representation=shape.to_s())
                        )
                    rule_cat.violations.append(v_item)
                    violation_idx += 1

            if rule_cat.count > 0:
                categories.append(rule_cat)

        return DRCReportData(source_path=gds_path, categories=categories)

src/klayout_drc/repair_executor.py:
"""Execute a candidate in a bounded, credential-free Bubblewrap worker."""
import ast
from dataclasses import dataclass
from functools import lru_cache
import os
from pathlib import Path
import resource
import shutil
import signal
import stat
import subprocess
import sys
import tempfile
import time
from .config import DEFAULT_TIMEOUT_SECONDS

EXEC_STATUS_SUCCESS = "success"
EXEC_STATUS_SYNTAX_ERROR = "syntax_error"
EXEC_STATUS_NONZERO_EXIT = "nonzero_exit"
EXEC_STATUS_TIMEOUT = "timeout"
EXEC_STATUS_MISSING_OUTPUT = "missing_output"
WORKER_ENV = {"PATH": "/usr/bin:/bin", "LANG": "C.UTF-8", "HOME": "/tmp",
              "PYTHONNOUSERSITE": "1", "PYTHONDONTWRITEBYTECODE": "1"}


@lru_cache(maxsize=1)
def sandbox_availability() -> str | None:
    executable = shutil.which("bwrap")
    if not executable:
        return "Bubblewrap is not installed. Candidate execution is blocked."
    try:
        command = [executable, "--unshare-all", "--unshare-user", "--disable-userns", "--die-with-parent",
                   "--ro-bind", "/usr", "/usr", "--ro-bind", "/lib", "/lib",
                   "--ro-bind", "/lib64", "/lib64", "--proc", "/proc", "--dev", "/dev",
                   "--size", "16777216", "--tmpfs", "/tmp",
                   "--ro-bind", str(Path(__file__).with_name("worker_policy.py")), "/worker_policy.py"]
        runtime = Path(sys.prefix)
        if (runtime / "pyvenv.cfg").exists():
            command += ["--ro-bind", str(runtime), "/runtime"]
            python = "/runtime/bin/python"
        else:
            python = sys.executable
        command += ["--", python, "-I", "-c",
                    "import runpy; runpy.run_path('/worker_policy.py')['install'](); import klayout.db"]
        probe = subprocess.run(command, env=WORKER_ENV, capture_output=True, text=True, timeout=10)
        if probe.returncode:
            return f"Bubblewrap isolation unavailable: {probe.stderr.strip()}"
    except (OSError, subprocess.TimeoutExpired) as exc:
        return f"Bubblewrap isolation unavailable: {exc}"
    return None


@dataclass(frozen=True)
class ExecutionResult:
    status: str
    exit_code: int | None
    duration_seconds: float
    stdout: str
    stderr: str
    output_gds: Path | None
    error_message: str | None = None
    peak_rss_bytes: int | None = None


class RepairExecutor:
    def __init__(self, candidate_script, input_gds, output_gds,
                 timeout_seconds=DEFAULT_TIMEOUT_SECONDS, python_bin=sys.executable,
                 memory_bytes=2*1024**3, max_output_bytes=64*1024**2, max_log_bytes=1024**2):
        self.candidate_script = Path(candidate_script).resolve()
        self.input_gds = Path(input_gds).resolve()
        self.output_gds = Path(output_gds).absolute()
        self.timeout_seconds = timeout_seconds
        self.python_bin = Path(python_bin).absolute()
        self.memory_bytes = memory_bytes
        self.max_output_bytes = max_output_bytes
        self.max_log_bytes = max_log_bytes

    def _check_syntax(self):
        try:
            ast.parse(self.candidate_script.read_text(), filename=str(self.candidate_script))
        except (SyntaxError, OSError) as exc:
            return f"{type(exc).__name__}: {exc}"
        return None

    def _sandbox_command(self, output_dir):
        command = [shutil.which('bwrap'), '--unshare-all', '--unshare-user', '--die-with-parent', '--new-session',
                   '--cap-drop', 'ALL', '--disable-userns', '--proc', '/proc', '--dev', '/dev', '--size', '16777216', '--tmpfs', '/tmp']
        for directory in ('/usr', '/lib', '/lib64'):
            if Path(directory).exists():
                command += ['--ro-bind', directory, directory]
        if Path('/etc/ld.so.cache').exists():
            command += ['--ro-bind', '/etc/ld.so.cache', '/etc/ld.so.cache']
        runtime = self.python_bin.parent.parent
        if (runtime / 'pyvenv.cfg').exists():
            command += ['--ro-bind', str(runtime), '/runtime']
            python = '/runtime/bin/python'
        else:
            python = str(self.python_bin.resolve())
            if not python.startswith('/usr/'):
                raise ValueError('Worker Python must be a venv or a system /usr runtime')
        command += ['--ro-bind', str(self.input_gds), '/input.gds',
                    '--ro-bind', str(self.candidate_script), '/candidate.py',
                    '--ro-bind', str(Path(__file__).with_name('worker_policy.py')), '/worker_policy.py',
                    '--bind', str(output_dir), '/output', '--chdir', '/output']
        # Set limits inside the new user/PID namespace, before loading candidate code.
        adapter = (
            "import resource,runpy,sys\n"
            f"resource.setrlimit(resource.RLIMIT_AS, ({self.memory_bytes}, {self.memory_bytes}))\n"
            f"resource.setrlimit(resource.RLIMIT_CPU, ({max(1,int(self.timeout_seconds))}, {max(1,int(self.timeout_seconds))}))\n"
            f"resource.setrlimit(resource.RLIMIT_FSIZE, ({self.max_output_bytes}, {self.max_output_bytes}))\n"
            "resource.setrlimit(resource.RLIMIT_NPROC, (64,64))\n"
            "resource.setrlimit(resource.RLIMIT_NOFILE, (64,64))\n"
            "runpy.run_path('/worker_policy.py')['install']()\n"
            "sys.argv=['/candidate.py','/input.gds','/output/patched.gds']\n"
            "mod=runpy.run_path('/candidate.py',run_name='__main__')\n"
            "from pathlib import Path\n"
            "if not Path('/output/patched.gds').exists() and callable(mod.get('fix_layout')):\n"
            "    mod['fix_layout']('/input.gds','/output/patched.gds')\n"
        )
        return command + ['--', python, '-I', '-c', adapter]

    def execute(self):
        syntax = self._check_syntax()
        if syntax:
            return ExecutionResult('syntax_error', 1, 0., '', syntax, None, syntax)
        blocked = sandbox_availability()
        if blocked:
            return ExecutionResult('blocked', None, 0., '', blocked, None, blocked)
        if self.output_gds.resolve() in (self.input_gds, self.candidate_script):
            return ExecutionResult('nonzero_exit', None, 0., '', '', None, 'Output aliases an immutable input')
        start = time.monotonic()
        with tempfile.TemporaryDirectory(prefix='drc-worker-') as tmp:
            scratch = Path(tmp)
            output = scratch / 'output'; output.mkdir()
            stdout_path, stderr_path = scratch/'stdout', scratch/'stderr'
            reason, status = None, None
            peak_rss = None
            proc = None
            try:
                with stdout_path.open('wb') as stdout, stderr_path.open('wb') as stderr:
                    proc = subprocess.Popen(self._sandbox_command(output), env=WORKER_ENV,
                                            stdout=stdout, stderr=stderr, start_new_session=True)
                    while proc.poll() is None:
                        measured = self._process_tree_rss(proc.pid)
                        if measured is not None:
                            peak_rss = max(peak_rss or 0, measured)
                        if time.monotonic()-start > self.timeout_seconds:
                            reason, status = 'Candidate timeout: exceeded wall-time limit', 'timeout'
                        elif stdout_path.stat().st_size + stderr_path.stat().st_size > self.max_log_bytes:
                            reason, status = 'Candidate exceeded log limit', 'nonzero_exit'
                        elif self._output_usage(output) > self.max_output_bytes:
                            reason, status = 'Candidate exceeded output limit', 'nonzero_exit'
                        if reason:
                            os.killpg(proc.pid, signal.SIGKILL); break
                        time.sleep(.02)
                    proc.wait()
                    # bwrap --die-with-parent owns its PID namespace. Kill remaining host group too.
                    try:
                        os.killpg(proc.pid, signal.SIGKILL)
                    except ProcessLookupError:
                        pass
                out = stdout_path.read_bytes()[:self.max_log_bytes].decode(errors='replace')
                err = stderr_path.read_bytes()[:self.max_log_bytes].decode(errors='replace')
                candidate = output/'patched.gds'
                if reason:
                    pass
                elif proc.returncode:
                    status = 'blocked' if err.startswith('bwrap:') else 'nonzero_exit'
                    reason = f'Worker exited with code {proc.returncode}: {err.strip()}'
                elif candidate.is_symlink() or not candidate.is_file() or not candidate.stat().st_size:
                    status, reason = 'missing_output', 'Worker did not produce a regular, nonempty patched.gds'
                elif self._output_usage(output) > self.max_output_bytes or stdout_path.stat().st_size + stderr_path.stat().st_size > self.max_log_bytes:
                    status, reason = 'nonzero_exit', 'Candidate exceeded output/log limit'
                else:
                    self.output_gds.parent.mkdir(parents=True, exist_ok=True)
                    if self.output_gds.exists() or self.output_gds.is_symlink():
                        self.output_gds.unlink()
                    shutil.copyfile(candidate, self.output_gds)
                    status = 'success'
                return ExecutionResult(status, proc.returncode, time.monotonic()-start, out, err,
                                       self.output_gds if status == 'success' else None, reason, peak_rss)
            except (OSError, ValueError) as exc:
                return ExecutionResult('blocked' if proc is None else 'nonzero_exit', None,
                                       time.monotonic()-start, '', str(exc), None, str(exc))
            finally:
                if proc is not None and proc.poll() is None:
                    try:
                        os.killpg(proc.pid, signal.SIGKILL)
                    except ProcessLookupError:
                        pass
                    proc.wait()

    def _output_usage(self, directory):
        total = 0
        for count, path in enumerate(directory.rglob('*')):
            if count >= 1024:
                return self.max_output_bytes + 1
            try:
                info = path.lstat()
            except FileNotFoundError:
                continue
            if stat.S_ISREG(info.st_mode):
                total += info.st_size
        return total

    @staticmethod
    def _process_tree_rss(pid):
        """Sample host-visible worker RSS. The maximum is a sampled lower bound."""
        pending, seen, total = [pid], set(), 0
        measured = False
        while pending:
            current = pending.pop()
            if current in seen:
                continue
            seen.add(current)
            try:
                status = Path(f'/proc/{current}/status').read_text()
                line = next((line for line in status.splitlines() if line.startswith('VmRSS:')), None)
                if line:
                    total += int(line.split()[1])*1024; measured = True
                children = Path(f'/proc/{current}/task/{current}/children').read_text()
                pending.extend(map(int, children.split()))
            except (OSError, ValueError):
                pass
        return total if measured else None

src/klayout_drc/validator.py:
"""Layout integrity validator for candidate layouts.

Verifies that patched GDS files conform to basic physical invariants:
valid top cell, preserved DBU, non-empty shapes, and reasonable bounding box bounds.
"""

from dataclasses import dataclass, field
from pathlib import Path
import klayout.db as db

from .config import DRCError


class LayoutValidationError(DRCError):
    """Raised when a candidate layout fails structural integrity checks."""
    pass


@dataclass(frozen=True)
class ValidationResult:
    """Outcome of layout integrity validation."""

    is_valid: bool
    top_cell_name: str
    dbu_um: float
    total_shapes: int
    bbox_um: tuple[float, float, float, float]
    violations: list[str] = field(default_factory=list)

    def to_dict(self) -> dict:
        """Convert validation result to dictionary."""
        return {
            "is_valid": self.is_valid,
            "top_cell_name": self.top_cell_name,
            "dbu_um": self.dbu_um,
            "total_shapes": self.total_shapes,
            "bbox_um": list(self.bbox_um),
            "violations": self.violations,
        }


class LayoutValidator:
    """Validates structural layout integrity and checks for destructive edits."""

    def __init__(
        self,
        patched_gds: Path,
        reference_gds: Path | None = None,
        allowed_layers: set[tuple[int, int]] | None = None,
        protected_cells: set[str] | None = None,
        preservation: dict | None = None,
        top_cell: str | None = None,
    ) -> None:
        """Initialize validator with target patched GDS and optional reference GDS.

        Args:
            patched_gds: Path to the layout to validate.
            reference_gds: Path to baseline layout before patch.
            allowed_layers: Optional set of allowed (layer, datatype) tuples that may be edited.
            protected_cells: Optional set of cell names that must remain immutable.
        """
        self.patched_gds = Path(patched_gds).resolve()
        self.reference_gds = Path(reference_gds).resolve() if reference_gds else None
        self.allowed_layers = allowed_layers
        self.protected_cells = protected_cells
        self.preservation = preservation or {}
        self.top_cell = top_cell

    def validate(self) -> ValidationResult:
        """Perform comprehensive layout integrity checks.

        Returns:
            ValidationResult: Detailed validation outcome.
        """
        violations: list[str] = []

        if not self.patched_gds.exists() or self.patched_gds.stat().st_size == 0:
            return ValidationResult(
                is_valid=False,
                top_cell_name="unknown",
                dbu_um=0.0,
                total_shapes=0,
                bbox_um=(0.0, 0.0, 0.0, 0.0),
                violations=["Patched GDS file does not exist or is empty (0 bytes)."],
            )

        layout = db.Layout()
        try:
            layout.read(str(self.patched_gds))
        except Exception as exc:
            return ValidationResult(
                is_valid=False,
                top_cell_name="corrupt",
                dbu_um=0.0,
                total_shapes=0,
                bbox_um=(0.0, 0.0, 0.0, 0.0),
                violations=[f"KLayout failed to parse GDS layout: {exc}"],
            )

        # 1. Check top cell
        top_cells = list(layout.top_cells())
        top_cell = layout.cell(self.top_cell) if self.top_cell else (top_cells[0] if len(top_cells) == 1 else None)
        if top_cell is None:
            violations.append("Layout has no top cell defined.")
            top_cell_name = "none"
        else:
            top_cell_name = top_cell.name

        # 2. Check total shapes in top cell (prevent 'delete-all' cheating)
        total_shapes = 0
        if top_cell is not None:
            for layer_idx in layout.layer_indexes():
                shapes = top_cell.shapes(layer_idx)
                total_shapes += sum(1 for _ in _recursive_shapes(top_cell, layer_idx))

        if total_shapes == 0:
            violations.append("Layout contains 0 shapes in top cell (all geometry was deleted).")

        # 3. Check DBU
        dbu = layout.dbu
        if dbu <= 0:
            violations.append(f"Invalid database unit (DBU <= 0): {dbu}")

        # 4. Check bounding box sanity
        bbox = top_cell.bbox() if top_cell else db.Box()
        if bbox.empty():
            violations.append("Top-cell bounding box is empty.")
            bbox_um = (0.0, 0.0, 0.0, 0.0)
        else:
            bbox_um = (
                bbox.left * dbu,
                bbox.bottom * dbu,
                bbox.right * dbu,
                bbox.top * dbu,
            )

        # 5. Check against reference layout if provided
        if self.reference_gds and self.reference_gds.exists():
            ref_layout = db.Layout()
            try:
                ref_layout.read(str(self.reference_gds))
                ref_top = ref_layout.cell(self.top_cell) if self.top_cell else ref_layout.top_cell()
                if ref_top and top_cell_name != "none" and ref_top.name != top_cell_name:
                    violations.append(
                        f"Top-cell name mismatch: expected '{ref_top.name}', got '{top_cell_name}'."
                    )
                if abs(ref_layout.dbu - dbu) > 1e-9:
                    violations.append(
                        f"DBU mismatch: original layout DBU is {ref_layout.dbu}, patched is {dbu}."
                    )

                # Check protected cells
                protected = self.protected_cells if self.protected_cells is not None else {c.name for c in ref_layout.each_cell() if c != ref_top}
                if protected:
                    for pcell_name in protected:
                        ref_c = ref_layout.cell(pcell_name)
                        patch_c = layout.cell(pcell_name)
                        if ref_c is not None:
                            if patch_c is None:
                                violations.append(f"Protected master cell '{pcell_name}' was removed in patched layout.")
                            elif _cell_content(ref_layout, ref_c) != _cell_content(layout, patch_c):
                                violations.append(f"Protected master cell '{pcell_name}' contents changed.")
                # Protect placements of protected masters, including top-level instances.
                for parent in ref_layout.each_cell():
                    patch_parent = layout.cell(parent.name)
                    before_instances = _protected_instances(ref_layout, parent, protected)
                    after_instances = _protected_instances(layout, patch_parent, protected) if patch_parent else ()
                    if before_instances != after_instances:
                        violations.append(f"Protected instance definitions changed in '{parent.name}'")
            except Exception as exc:
                violations.append(f"Could not load reference GDS for comparison: {exc}")

        if top_cell is not None:
            for layer_key, expected in self.preservation.get("component_counts", {}).items():
                layer, datatype = map(int, layer_key.split("/"))
                idx = layout.find_layer(layer, datatype)
                observed = db.Region(top_cell.begin_shapes_rec(idx)).merged().count() if idx is not None else 0
                if observed != expected:
                    violations.append(f"Component preservation failed on {layer_key}: expected {expected}, observed {observed}")
            if self.reference_gds and self.preservation.get("protected_regions"):
                for region in self.preservation["protected_regions"]:
                    layer, datatype = region["layer"]
                    window = db.Region(db.Box(*region["box_dbu"]))
                    a = ref_layout.find_layer(layer, datatype)
                    b = layout.find_layer(layer, datatype)
                    before = db.Region(ref_top.begin_shapes_rec(a)) if a is not None else db.Region()
                    after = db.Region(top_cell.begin_shapes_rec(b)) if b is not None else db.Region()
                    if not ((before ^ after) & window).is_empty():
                        violations.append(f"Protected region changed on {layer}/{datatype}")
        is_valid = len(violations) == 0
        return ValidationResult(
            is_valid=is_valid,
            top_cell_name=top_cell_name,
            dbu_um=dbu,
            total_shapes=total_shapes,
            bbox_um=bbox_um,
            violations=violations,
        )


def _recursive_shapes(cell, layer):
    iterator = cell.begin_shapes_rec(layer)
    while not iterator.at_end():
        yield iterator.shape()
        iterator.next()


def _cell_content(layout, cell):
    shapes = tuple(sorted((str(layout.get_info(idx)), tuple(sorted(s.to_s() for s in cell.shapes(idx).each())))
                          for idx in layout.layer_indexes() if not cell.shapes(idx).is_empty()))
    instances = tuple(sorted((layout.cell(i.cell_index).name, str(i.cplx_trans), str(i.a), str(i.b), i.na, i.nb) for i in cell.each_inst()))
    return shapes, instances


def _protected_instances(layout, cell, protected):
    return tuple(sorted((layout.cell(i.cell_index).name, str(i.cplx_trans), str(i.a), str(i.b), i.na, i.nb)
                        for i in cell.each_inst() if layout.cell(i.cell_index).name in protected))
